def remove_duplicates(numbers: List[int]) -> List[int]:
    seen = set()
    duplicates = set()
    result = []
    for num in numbers:
        if num in seen:
            duplicates.add(num)
        else:
            seen.add(num)
            result.append(num)
    return [num for num in result if num not in duplicates]

