from typing import List
from math import isqrt

def is_prime(num: int) -> bool:
    if num < 2:
        return False
    for i in range(2, isqrt(num) + 1):
        if num % i == 0:
            return False
    return True

def generate_fibonacci_up_to(n: int) -> List[int]:
    fib = [0, 1]
    while True:
        next_fib = fib[-1] + fib[-2]
        if next_fib > n:
            break
        fib.append(next_fib)
    return fib

def prime_fib(n: int) -> int:
