initial_code:
from typing import List

def encode(message: str) -> str:
    """
    Write a function that takes a message, and encodes in such a way that it swaps case of all letters, 
    replaces all vowels in the message with the letter that appears 2 places ahead of that vowel in the english alphabet. 
    Assume only letters.
    """
    result = []
    for char in message:
        if char.isalpha():
            if char.islower():
                swapped = char.upper()
            else:
                swapped = char.lower()

            if char.lower() in 'aeiou':
                if char.lower() == 'a':
                    new_char = 'c'
                elif char.lower() == 'e':
                    new_char = 'g'
                elif char.lower() == 'i':
                    new_char = 'k'
                elif char.lower() == 'o':
                    new_char = 'q'
                elif char.lower() == 'u':
                    new_char = 'y'
                swapped = new_char.upper() if swapped.islower() else new_char.lower()

            result.append(swapped)
        else:
            result.append(char)

    return ''.join(result)

