    if len(lst) > 1:
        prev = lst[0]
        for num in lst[1:]:
            if num < prev:
                return False
            if num == prev:
                # Check if there are more than 1 duplicate
                if lst.count(prev) > 1:
                    return False
            prev = num
    return True
