initial_code:
from typing import List

def is_nested(string: str) -> bool:
    stack = []
    max_depth = 0
    for char in string:
        if char == '[':
            stack.append(char)
            if len(stack) > max_depth:
                max_depth = len(stack)
        elif char == ']':
            if not stack:
                return False
            stack.pop()
    return max_depth > 1

