def fix_spaces(text: str) -> str:
    result = []
    consecutive_spaces = 0

    for char in text:
        if char == ' ':
            consecutive_spaces += 1
            if consecutive_spaces > 2:
                result.append('-')
                consecutive_spaces = 0
            else:
                result.append('_')
        else:
            if consecutive_spaces > 0:
                result.append('_' * consecutive_spaces)
                consecutive_spaces = 0
            result.append(char)

    if consecutive_spaces > 0:
        result.append('_' * consecutive_spaces)

    return ''.join(result)

