initial_code:
from typing import List

def solve(s: str) -> str:
    result = []
    has_letter = False
    for char in s:
        if char.isalpha():
            has_letter = True
            result.append(char.swapcase())
        else:
            result.append(char)
    if not has_letter:
        return ''.join(reversed(result))
    return ''.join(result)

